public:
    bool start();               // 加载 eBPF，探测挂点，失败降级
    void stop();
    bool isAvailable() const;   // eBPF 是否成功 attach

    void setSessionActive(uint32_t hciIndex, const std::string& bdaddr, bool active);
    bool getStats(uint32_t hciIndex, const std::string& bdaddr, BtTrafficStats* out) const;
    std::string attachedHookName() const;

private:
    void* bpfObj_ = nullptr;
    void* link_ = nullptr;
    int mapStatsFd_ = -1;
    int mapControlFd_ = -1;
    bool attached_ = false;
    std::string hookName_;
    std::string fallbackReason_;

    bool tryAttachTracepoint();
    bool tryAttachFentry();
    bool tryAttachKprobe();
};
