                                  bool ebpfAvailable);
    void setStallThresholds(uint64_t lightMs, uint64_t severeMs);
    void setMinBytesPerWindow(uint64_t bytes);
private:
    uint64_t stallLightMs_ = 300;
    uint64_t stallSevereMs_ = 1000;
    uint64_t minBytesPerWindow_ = 1000;
    std::chrono::system_clock::time_point lastTick_;
    uint64_t lastBytes_ = 0;
};
```

### 4.7 数据流程设计

#### 4.7.1 Phase 1 数据流

```
Wi-Fi RSSI ─────────────┐
(WeakNetMgr.NetInfo)     │
                         ▼
蓝牙 RSSI ──► BandConflictDetector.feedSample()
(BtMonitor       │
 .getRssiSnapshot)▼
              BandConflictDetector.detect()
                         │
                         ▼  (15s, network_quality_thread)
              EventManager.emitNetworkQualityChanged("band_conflict")

BtMonitor.refreshDeviceStates() (3s)
    ├──► parseDeviceProperties → 读取 TxPower
    ├──► estimateDistance(rssi)  → 写入 BtDeviceInfo.estimatedDistance
    └──► refreshAudioTransports() → 遍历 MediaTransport1
              └──► calculateAudioScore → BtAudioQuality
                         │
                         ▼
              EventManager.emitBluetoothDeviceChanged("audio_quality"/"distance")
```

#### 4.7.2 Phase 2 融合数据流

```
D-Bus PropertiesChanged (State=active)
    │
    ▼
BtMonitor.onTransportStateChanged()
    │
    ▼ 写 BPF Map (SessionControl.enabled=1)
BtAudioAnalyzer.setSessionActive()
    │
    ▼ eBPF 内核态（仅在 enabled 时统计）
a2dp_media.bpf.c: kprobe/tracepoint l2cap 流量 → BPF_MAP (per device 聚合)
    │
    ▼ 用户态每秒读
BtAudioAnalyzer.getStats()
    │
    ▼
BtAudioFusion.evaluate(transport, stats)
    │   ├── effective_active = active && bytes>min
    │   ├── suspected_stall  = active && gap>threshold
    │   └── 时间加权 Delay
    ▼
BtAudioQuality (升级版) → EventManager
```

### 4.8 线程调度与集成

**不新增线程**，严格复用现有线程：

| 工作内容 | 所属线程 | 调用点 | 频率 |
| -------- | -------- | ------ | ---- |
| 频段冲突 feed + detect | `network_quality_thread` | server.cpp 循环内 | 15s |
| 距离估算 + A2DP D-Bus 刷新 | 蓝牙监测线程 | `refreshDeviceStates()` 内 | 3s |
| eBPF map 读取 + 融合评估 | 蓝牙监测线程 | `refreshDeviceStates()` 内（Phase 2） | 3s |
| D-Bus PropertiesChanged 订阅 | 蓝牙监测线程 | `initialize()` 时加 match | 事件驱动 |
| 低频校准轮询 | 蓝牙监测线程 | 每 10-30s `GetAll` | 兜底 |

### 4.9 NetInfo 扩展

在 `net_info.hpp` 中新增字段，并扩展 `toJson()`/`fromJson()`/`isValid()`/`needsUpdate()`：

```cpp
class NetInfo {
    // ... 现有字段 ...
private:
    double bt_distance_ = -1.0;            // 蓝牙设备距离（米）
    std::string bt_audio_quality_;          // 蓝牙音频质量等级
    bool band_conflict_ = false;            // 是否检测到频段冲突
    double band_conflict_confidence_ = 0.0; // 频段冲突置信度
public:
    void setBtDistance(double d) { bt_distance_ = d; }
    double btDistance() const { return bt_distance_; }
    bool hasBtDistance() const { return bt_distance_ >= 0.0; }
    void setBtAudioQuality(const std::string& q) { bt_audio_quality_ = q; }
    const std::string& btAudioQuality() const { return bt_audio_quality_; }
    void setBandConflict(bool v) { band_conflict_ = v; }
    bool bandConflict() const { return band_conflict_; }
    void setBandConflictConfidence(double c) { band_conflict_confidence_ = c; }
    double bandConflictConfidence() const { return band_conflict_confidence_; }
};
```

