content.content:
=== S1: applyPendingActions + generation gate ===

void EdgeTelemetryExporter::applyPendingActions(const std::string& response_body) {
    const auto actions = parsePendingActions(response_body);
    if (actions.empty()) return;

    for (const auto& action : actions) {
        std::string error;
        bool ok = false;

        const bool trialable = weaknet_dbus::isTrialableKey(action.key);
        const bool v2_metadata = action.generation_present || !action.claim_token.empty() ||
                                 !action.nonce.empty();

        // 应答丢失→遥测重发→云端重放 pending_actions 是常态路径。
        // 已执行过的 action_id 回执**首次的真实结果**，绝不重执行（重执行会重置
        // TRIAL deadline、把看门狗无限续期，并泛洪 action-results）。
        // 注意：不能固定回 APPLIED——首次被拒的动作若谎报成功，云端会把
        // 未生效的配置记成已应用。
        auto it = executed_action_ids_.find(action.action_id);
        if (it != executed_action_ids_.end()) {
            const bool first_ok = it->second;
            LOG_INFO(weaknet_dbus::LogModule::SYSTEM,
                     "云端动作已执行过，直接回执不重放: " << action.action_id
                     << " (first=" << (first_ok ? "APPLIED" : "REJECTED") << ")");
            queueActionResult(action.action_id, first_ok ? "APPLIED" : "REJECTED",
                              first_ok ? "applied_duplicate" : "rejected_duplicate",
                              action.claim_token, action.generation);
            continue;
        }

        // fail-closed：trialable key 或携带 v2 元数据的动作必须带有效 generation，
        // 否则 generation=0 会绕过 stale 判定、且永远推进不了 last_applied。
        if ((trialable || v2_metadata) && (!action.generation_present || action.generation == 0)) {
            error = "missing_or_invalid_generation";
        } else {
            const bool stale = action.generation > 0 &&
                               config_txn_ &&
                               action.generation <= config_txn_->lastAppliedGeneration();

        if (stale) {
            error = "stale_generation";
            LOG_ERROR(weaknet_dbus::LogModule::SYSTEM,
                      "云端动作被拒绝（generation 过期）: " << action.key
                      << " gen=" << action.generation
                      << " last=" << config_txn_->lastAppliedGeneration());
        } else if (trialable && config_txn_) {
            // TRIAL 路径：先记账（含 prior_values 快照），再落值。
            auto* cfg = const_cast<weaknet_dbus::WeakNetConfig*>(&config_);
            const auto state = config_txn_->state();
            if (state == weaknet_dbus::ConfigState::TRIAL) {
                ok = config_txn_->extendTrial(*cfg, action.key, action.value,
                                              action.action_id, action.generation,
                                              &error);
            } else {
