class UsingInterfaceManager {
public:
    /// 线程安全懒汉单例
    static std::shared_ptr<UsingInterfaceManager> getInstance();

    /**
     * @brief 启动后台监听（可重复调用，幂等）
     *
     * 内部会启动一个 Netlink 监听线程，阻塞在 recv() 上等待路由事件。
     * 如果已经启动则直接返回。
     */
    void start();

    /**
     * @brief 获取当前用于上网的网卡名
     * @return 网卡名（如 "wlan0"）；无默认路由时返回空字符串
     */
    std::string getCurrentInterface();

    /**
     * @brief 获取当前上网方法标志位
     * @return UsingMethodFlag 组合（如 IPv4Default | IPv6Default）
     */
    uint32_t getMethodFlags();

    ~UsingInterfaceManager();

private:
    UsingInterfaceManager();
    UsingInterfaceManager(const UsingInterfaceManager&) = delete;
    UsingInterfaceManager& operator=(const UsingInterfaceManager&) = delete;

    static std::once_flag s_onceFlag;
    static std::shared_ptr<UsingInterfaceManager> s_instance;

// pimpl 完整定义处提供析构：结束 netlink 事件循环线程（置停标志 + join），
// 避免 detached 线程在单例析构后野访问；再释放 Impl。
#if defined(__linux__)
UsingInterfaceManager::~UsingInterfaceManager() {
    if (impl_) {
        impl_->running.store(false);       // 通知事件循环退出
        if (impl_->worker.joinable()) impl_->worker.join();  // 等待线程结束，避免 use-after-free
        delete impl_;
        impl_ = nullptr;
    }
}
#else
UsingInterfaceManager::~UsingInterfaceManager() = default;
#endif

/**
 * @brief 启动后台 netlink 事件监听线程
 *
 * 幂等调用：若线程已在运行则不重复启动；若线程已退出但未 join 则先 join。
 * 线程在析构时安全停止（detach 不被调用，始终保持 joinable）。
 */
void UsingInterfaceManager::start() {
#if defined(__linux__)
    std::lock_guard<std::mutex> lk(stateMutex_);
    if (impl_ == nullptr) impl_ = new Impl();
    if (!impl_->running.load()) {
        // 先 join 旧线程（如果线程退出但未 join，worker 仍 joinable）
        if (impl_->worker.joinable()) impl_->worker.join();
        impl_->worker = std::thread([this]{ impl_->eventLoop(this); });
        // 不 detach：保持 joinable，析构时 join 等待线程安全退出
    }
#else
    (void)stateMutex_;

