5:while [[ $# -gt 0 ]]; do case "$1" in --phase) phase=${2:?}; shift ;; --current-step) current=${2:?}; shift ;; --next-step) next=${2:?}; shift ;; --freeze-planning-baseline) freeze_plan=1 ;; --refresh-planning-baseline) refresh_plan=1 ;; --freeze-implementation-base) freeze_implementation=1 ;; --adopt-path) adopted+=("${2:?}"); shift ;; *) echo "[ERR] unknown option: $1" >&2; exit 2 ;; esac; shift; done
6-(( freeze_plan + refresh_plan <= 1 )) || { echo '[ERR] initial freeze and planning-baseline refresh are mutually exclusive' >&2; exit 2; }
7-if [[ "$refresh_plan" -eq 1 ]]; then
8-  [[ "$freeze_implementation" -eq 0 && "${#adopted[@]}" -eq 0 ]] || { echo '[ERR] planning refresh cannot move the implementation base or adopt new paths' >&2; exit 2; }
9-  [[ -z "$phase" || "$phase" == implementing ]] || { echo '[ERR] planning refresh resumes at phase=implementing' >&2; exit 2; }
10-  phase=implementing; [[ -n "$current" ]] || current=planning-reapproved; [[ -n "$next" ]] || next='Resume the first unchecked task, or begin Evaluation when all tasks are complete'
11-fi
