14-if [[ -n "$active" ]]; then isolation_status=$(harness_isolation_node status "$active"); if [[ "$(node -p "JSON.parse(process.argv[1]).worktree_kind" "$isolation_status")" == linked && "$(node -p "JSON.parse(process.argv[1]).local_lease||''" "$isolation_status")" != '' ]]; then [[ "$freeze_plan" -eq 0 && "$refresh_plan" -eq 0 && "$freeze_implementation" -eq 0 && "${#adopted[@]}" -eq 0 && ( -z "$phase" || "$phase" == implementing ) ]] || { echo '[ERR] isolation pilot permits only implementing cursor updates; planning/base/ownership changes stay in the coordinator worktree' >&2; exit 4; }; fi; fi
