if (it == devices_.end()) {
    // ---- 新设备 ----
    info.lastSeen = now;
    info.lastUpdated = now;
    if (info.rssiDbm != 0 && info.rssiDbm > -1000) {
        info.rssiHistory.push_back(info.rssiDbm);
    }
    devices_[info.macAddress] = info;

    // 轮询快照：仅登记初次发现与时间戳，严禁推进基线或连续计数
    if (tracker_) {
        WirelessDeviceKey k;
        if (eventStore_) {
            k.site_id = eventStore_->config().site_id;
            k.gateway_id = eventStore_->config().gateway_id;
        }
        k.device_address = info.macAddress;
        k.address_type = (info.addressType == "random") ? BtAddressType::LeRandom : BtAddressType::LePublic;
        struct timespec ts{};
        clock_gettime(CLOCK_MONOTONIC, &ts);
        uint64_t mono_ns = static_cast<uint64_t>(ts.tv_sec) * 1000000000ULL + ts.tv_nsec;
        uint64_t wall_ms = std::chrono::duration_cast<std::chrono::milliseconds>(now.time_since_epoch()).count();
        tracker_->registerDeviceSnapshot(k, wall_ms, mono_ns);
    }

    // 生成事件
    BtEvent ev;
    ev.type = BtEvent::Type::DeviceFound;
    ev.adapterMac = adapterState_.macAddress;
    ev.deviceMac = info.macAddress;
    ev.deviceName = info.name.empty() ? info.alias : info.name;
    ev.rssiDbm = info.rssiDbm;
    ev.message = "New device found: " + ev.deviceName +
                 " (" + info.macAddress + ")" +
                 (info.rssiDbm != 0 ? " RSSI:" + std::to_string(info.rssiDbm) + "dBm" : "");
    ev.timestamp = now;
    {
        std::lock_guard<std::mutex> evLock(eventMutex_);
        pendingEvents_.push_back(ev);
    }
    LOG_INFO(LogModule::BLUETOOTH, "BtMonitor: " << ev.message);

} else {
