TEST(UsingInterfaceManagerLifecycleTest, StopIdempotentAndRestartable) {
    auto mgr = UsingInterfaceManager::getInstance();
    ASSERT_NE(mgr, nullptr);

    // 连续调用 stop 应当幂等且安全
    EXPECT_NO_THROW(mgr->stop());
    EXPECT_NO_THROW(mgr->stop());

    // 启动后再 stop 也应当安全
    EXPECT_NO_THROW(mgr->start());
    EXPECT_NO_THROW(mgr->stop());
    EXPECT_NO_THROW(mgr->stop());
}
