    // 停止无线事实上行：同样必须早于 ~ServerContext 释放 db_mgr，
    // 否则工作线程可能在数据库析构后读取事实。
    if (ctx.wireless_uplink) {
        ctx.wireless_uplink->stop();
        ctx.wireless_uplink.reset();
    }

    // 显式停止上网网卡监听线程：在 glog 和全局资源关闭前完成线程 join，
    // 杜绝静态单例析构时后台线程野访问已释放的日志设施。
    UsingInterfaceManager::getInstance()->stop();

    // 停止文件日志（在 glog 关闭之前）
