    // 清理glog。资源（DBus 连接 / service / weak_mgr）由 ~ServerContext 统一释放。
    google::ShutdownGoogleLogging();

    // 清理全局网络通信库（libcurl 全局资源释放）
    weaknet::EdgeTelemetryExporter::cleanupGlobal();

    return 0;
