/**
 * @file monitor_registry.cpp
 * @brief 监控器插件静态注册表实现
 *
 * 内部用函数级静态变量持有注册表（构造时注册，跨编译单元安全）。
 * instantiateAllPlugins 按 order() 升序返回。
 * 停止时由 server.cpp 在 join 全部线程后按 order() 逆序显式调用 stop()；
 * 插件 vector 析构顺序为反向构造顺序，不保证与 order() 逆序一致。
 */

#include "monitor_registry.hpp"

#include <algorithm>
#include <map>
#include <mutex>

#include "logger.hpp"

namespace weaknet_dbus {

namespace {

struct Registry {
    std::map<std::string, PluginFactory> factories;  ///< 名字 → 工厂（map 保序，去重）
    std::mutex mutex;
};

Registry& registry() {
    static Registry r;
    return r;
}

}  // namespace

void registerPlugin(const char* name, PluginFactory factory) {
    if (!name || !factory) return;
    auto& r = registry();
    std::lock_guard<std::mutex> lock(r.mutex);
    if (r.factories.find(name) != r.factories.end()) {
        LOG_WARNING(LogModule::SYSTEM, "monitor registry: duplicate plugin name '" << name
                    << "' ignored");
        return;
    }
    r.factories.emplace(name, std::move(factory));
}

std::vector<std::unique_ptr<IMonitorPlugin>> instantiateAllPlugins() {
    auto& r = registry();
    std::lock_guard<std::mutex> lock(r.mutex);

    std::vector<std::unique_ptr<IMonitorPlugin>> plugins;
    plugins.reserve(r.factories.size());
    for (auto& [name, factory] : r.factories) {
        auto plugin = factory();
        if (plugin) {
            plugin->name();  // 触发虚调用，确保动态类型完整
            plugins.push_back(std::move(plugin));
        }
    }

    // 按 order() 升序（依赖在前）
    std::stable_sort(plugins.begin(), plugins.end(),
                     [](const std::unique_ptr<IMonitorPlugin>& a,
                        const std::unique_ptr<IMonitorPlugin>& b) {
                         return a->order() < b->order();
                     });
    return plugins;
}

}  // namespace weaknet_dbus====HEADER
/**
 * @file monitor_registry.hpp
 * @brief 监控器插件静态注册表
 *
 * 编译期注册 + 运行期由 MonitorManager 持有并按 order 实例化的插件管理。
 *
 * 用法（在每个插件 .cpp 末尾注册自己）：
 *   static const bool _rtt_registered =
 *       (weaknet_dbus::registerPlugin("rtt",
 *           []{ return std::make_unique<RttPlugin>(); }), true);
 *
 * 启动/收尾（server.cpp）：
 *   auto plugins = weaknet_dbus::instantiateAllPlugins();
 *   for (auto& p : plugins) p->init(&ctx);
 *   for (auto& p : plugins) p->start(&ctx);
 *   // 停止按逆序
 */

#pragma once

#include <functional>
#include <memory>
#include <string>
#include <vector>

#include "monitor_plugin.hpp"

namespace weaknet_dbus {

using PluginFactory = std::function<std::unique_ptr<IMonitorPlugin>()>;

/**
 * @brief 注册插件工厂（编译期静态注册）
 *
 * @param name    插件唯一名（重复名会被拒绝并记录警告）
 * @param factory 工厂函数，返回插件实例
 */
void registerPlugin(const char* name, PluginFactory factory);

/**
 * @brief 实例化所有已注册插件，并按 order() 升序排序
 *
 * @return 按启动顺序排列的插件实例列表（停止时应逆序遍历）
 */
std::vector<std::unique_ptr<IMonitorPlugin>> instantiateAllPlugins();

// ---- 内置插件注册入口（server.cpp 启动前调用） ----

/// 注册 8 个传统监控器插件（iface/using_iface/rtt/rssi/tcp_loss/traffic/quality/bluetooth）
/// 注：jitter 已合并进 rtt（同一次 ping 采样上计算滑动窗口标准差），不再是独立插件。
void registerBuiltinPlugins();

/// 注册 6 个 eBPF 监控器插件（dns/wifi_loss/http_latency/process_profiler/tcp_retrans/tcp_conn）
void registerEbpfPlugins();

}  // namespace weaknet_dbus

