73	size_t writeCallback(char* ptr, size_t size, size_t nmemb, void* userdata) {
74	    const size_t total = size * nmemb;
75	    static_cast<std::string*>(userdata)->append(ptr, total);
76	    return total;
77	}
78	#endif
79	
80	std::string readUintField(const std::string& text, const std::string& key) {
81	    const std::string needle = key + "=";
82	    size_t pos = text.find(needle);
83	    if (pos == std::string::npos) return "";
84	    pos += needle.size();
85	    size_t end = text.find('\n', pos);
86	    if (end == std::string::npos) end = text.size();
87	    return text.substr(pos, end - pos);
88	}
