96	std::string EdgeWirelessUplinkExporter::buildBody(const WirelessUplinkPayload& payload,
97	                                                  std::string* error) {
98	    if (payload.device_id.empty()) {
99	        if (error) *error = "device_id 为空";
100	        return {};
101	    }
102	    if (payload.events.size() > EDGE_WIRELESS_MAX_EVENTS_PER_BATCH ||
103	        payload.incidents.size() > EDGE_WIRELESS_MAX_INCIDENTS_PER_BATCH ||
104	        payload.baselines.size() > EDGE_WIRELESS_MAX_BASELINES_PER_BATCH) {
105	        if (error) *error = "单批事实数超出契约上限";
106	        return {};
107	    }
108	    // 云端契约要求至少一组非空：空批不发送（避免无意义的 422）
109	    const bool env_present = payload.env_to_ms > payload.env_from_ms;
110	    if (payload.events.empty() && payload.incidents.empty() && payload.baselines.empty() &&
111	        !env_present) {
112	        if (error) *error = "空批";
113	        return {};
114	    }
115	
116	    std::ostringstream body;
117	    body << "{\"schema_version\":\"network.edge.wireless-events.v1\",";
118	    body << "\"device_id\":" << jsonStr(payload.device_id) << ",";
119	    // 网关自述的动作目录指纹（见 docs/网关动作目录版本契约.md）。
120	    // 目录内容在编译期由 ActionRegistry 构造函数固定，故只算一次；
121	    // 两端不一致即部署版本漂移，Policy 会 fail-closed 拒绝该网关的一切动作。
122	    static const std::string catalog_version =
123	        weaknet::actionCatalogVersion(weaknet::ActionRegistry::defaultInstance());
124	    body << "\"catalog_version\":" << jsonStr(catalog_version) << ",";
125	    body << "\"watermark_ms\":" << payload.watermark_ms << ",";
126	
127	    body << "\"events\":[";
128	    for (size_t i = 0; i < payload.events.size(); ++i) {
129	        const auto& ev = payload.events[i];
130	        if (i) body << ",";
131	        body << "{"
132	             << "\"event_id\":" << jsonStr(ev.event_id) << ","
133	             << "\"ts_ms\":" << ev.timestamp_ms << ","
134	             << "\"site_id\":" << jsonStr(ev.site_id) << ","
135	             << "\"gateway_id\":" << jsonStr(ev.gateway_id) << ","
136	             << "\"protocol\":" << jsonStr(toString(ev.protocol)) << ","
137	             << "\"device_address\":" << jsonStr(ev.device_address) << ","
138	             << "\"address_type\":" << jsonStr(toString(ev.address_type)) << ","
139	             << "\"hci_index\":" << ev.hci_index << ","
140	             << "\"event_type\":" << jsonStr(toString(ev.event_type)) << ","
141	             << "\"rssi_at_event_dbm\":"
142	             << (ev.rssi_at_event_dbm.has_value() ? std::to_string(*ev.rssi_at_event_dbm)
143	                                                  : std::string("null"))
144	             << ","
145	             << "\"raw_reason_code\":" << static_cast<int>(ev.raw_reason_code) << ","
146	             << "\"reason\":" << jsonStr(toString(ev.reason)) << ","
147	             << "\"source\":" << jsonStr(toString(ev.source)) << ","
148	             << "\"source_detail\":" << jsonStr(ev.source_detail) << ","
149	             << "\"details_json\":" << jsonStr(ev.details_json) << "}";
150	    }
151	    body << "],";
152	
153	    body << "\"incidents\":[";
154	    for (size_t i = 0; i < payload.incidents.size(); ++i) {
155	        const auto& inc = payload.incidents[i];
156	        if (i) body << ",";
157	        const std::vector<std::string> evidence =
158	            (i < payload.incident_evidence.size()) ? payload.incident_evidence[i]
159	                                                   : std::vector<std::string>{};
160	        body << "{"
161	             << "\"incident_id\":" << jsonStr(inc.incident_id) << ","
162	             << "\"site_id\":" << jsonStr(inc.site_id) << ","
163	             << "\"gateway_id\":" << jsonStr(inc.gateway_id) << ","
164	             << "\"started_at_ms\":" << inc.started_at_ms << ","
165	             << "\"last_event_ms\":" << inc.last_event_ms << ","
166	             << "\"resolved_at_ms\":"
167	             << (inc.resolved_at_ms.has_value() ? std::to_string(*inc.resolved_at_ms)
168	                                                : std::string("null"))
169	             << ","
170	             << "\"affected_devices\":" << inc.affected_devices << ","
171	             << "\"state\":" << jsonStr(toString(inc.state)) << ","
172	             << "\"suspected_cause\":"
173	             << (inc.suspected_cause.has_value() ? jsonStr(*inc.suspected_cause)
174	                                                 : std::string("null"))
175	             << ","
176	             << "\"evidence_event_ids\":" << jsonStringArray(evidence) << "}";
177	    }
178	    body << "],";
179	
180	    body << "\"baselines\":[";
181	    for (size_t i = 0; i < payload.baselines.size(); ++i) {
182	        const auto& b = payload.baselines[i];
183	        if (i) body << ",";
184	        body << "{"
185	             << "\"site_id\":" << jsonStr(b.key.site_id) << ","
186	             << "\"gateway_id\":" << jsonStr(b.key.gateway_id) << ","
187	             << "\"hci_index\":" << b.key.hci_index << ","
188	             << "\"protocol\":" << jsonStr(toString(b.key.protocol)) << ","
189	             << "\"address_type\":" << jsonStr(toString(b.key.address_type)) << ","
190	             << "\"device_address\":" << jsonStr(b.key.device_address) << ","
191	             << "\"baseline_rssi_dbm\":" << jsonNullableInt(b.baseline_rssi_dbm) << ","
192	             << "\"min_seen_rssi_dbm\":" << jsonNullableInt(b.min_seen_rssi_dbm) << ","
193	             << "\"max_seen_rssi_dbm\":" << jsonNullableInt(b.max_seen_rssi_dbm) << ","
194	             << "\"baseline_sample_count\":" << b.baseline_sample_count << ","
195	             << "\"state\":" << jsonStr(toString(b.state)) << "}";
196	    }
197	    body << "],";
198	
199	    // 环境窗口：承载深度内核快照（进程画像 Top N + 协议栈丢包归因 + 被动 TCP RTT 连接画像）。
200	    // 只有确实取到数据时才 available=true——绝不用空数组冒充"观测过且正常"。
201	    const bool has_process_data = !payload.top_processes.empty();
202	    const bool has_drop_data = payload.drop_stats.has_value();
203	    const bool has_tcp_rtt_data = payload.tcp_rtt_stats.has_value();
204	    body << "\"env_window\":{"
205	         << "\"available\":" << ((has_process_data || has_drop_data || has_tcp_rtt_data) ? "true" : "false") << ","
206	         << "\"link_type\":\"UNKNOWN\","
207	         << "\"wifi_anomaly\":false,"
208	         << "\"coexistence_warning\":false,"
209	         << "\"from_ms\":" << payload.env_from_ms << ","
210	         << "\"to_ms\":" << payload.env_to_ms << ","
211	         << "\"snapshots\":[";
212	
213	    bool first_snapshot = true;
214	    if (has_process_data) {
215	        body << "{\"kind\":\"process_top\",\"ts_ms\":" << payload.env_to_ms << ",\"top_processes\":[";
216	        for (size_t i = 0; i < payload.top_processes.size(); ++i) {
217	            const auto& p = payload.top_processes[i];
218	            if (i) body << ",";
219	            body << "{\"pid\":" << p.pid
220	                 << ",\"comm\":" << jsonStr(p.comm)
221	                 << ",\"tx_bytes\":" << p.txBytes
222	                 << ",\"tx_packets\":" << p.txPackets
223	                 << ",\"retrans_count\":" << p.retransCount << "}";
224	        }
225	        body << "]}";
226	        first_snapshot = false;
227	    }
228	    if (has_drop_data) {
229	        const auto& ds = *payload.drop_stats;
230	        if (!first_snapshot) body << ",";
231	        body << "{\"kind\":\"skb_drop_hist\",\"ts_ms\":" << payload.env_to_ms
232	             << ",\"total_drops\":" << ds.totalDrops << ",\"top_reasons\":[";
233	        for (size_t i = 0; i < ds.topReasons.size(); ++i) {
234	            const auto& r = ds.topReasons[i];
235	            if (i) body << ",";
236	            body << "{\"reason_code\":" << r.reasonCode
237	                 << ",\"reason_name\":" << jsonStr(r.reasonName)
238	                 << ",\"description\":" << jsonStr(r.humanDesc)
239	                 << ",\"protocol\":" << jsonStr(r.protocol)
240	                 << ",\"count\":" << r.count
241	                 << ",\"last_timestamp_ns\":" << r.lastTimestampNs << "}";
242	        }
243	        body << "]}";
244	        first_snapshot = false;
245	    }
246	    if (has_tcp_rtt_data) {
247	        const auto& rs = *payload.tcp_rtt_stats;
248	        if (!first_snapshot) body << ",";
249	        body << "{\"kind\":\"tcp_rtt_top\",\"ts_ms\":" << payload.env_to_ms
250	             << ",\"total_samples\":" << rs.totalSamples
251	             << ",\"active_connections\":" << rs.activeConns
252	             << ",\"avg_rtt_us\":" << rs.avgRttUs
253	             << ",\"p50_rtt_us\":" << rs.p50RttUs
254	             << ",\"p90_rtt_us\":" << rs.p90RttUs
255	             << ",\"p99_rtt_us\":" << rs.p99RttUs
256	             << ",\"top_connections\":[";
257	        for (size_t i = 0; i < rs.topConns.size(); ++i) {
258	            const auto& c = rs.topConns[i];
259	            if (i) body << ",";
260	            body << "{\"src\":" << jsonStr(c.saddr + ":" + std::to_string(c.sport))
261	                 << ",\"dst\":" << jsonStr(c.daddr + ":" + std::to_string(c.dport))
262	                 << ",\"srtt_us\":" << c.srttUs
263	                 << ",\"min_rtt_us\":" << c.minRttUs
264	                 << ",\"max_rtt_us\":" << c.maxRttUs
265	                 << ",\"snd_cwnd\":" << c.sndCwnd
266	                 << ",\"samples\":" << c.sampleCount << "}";
267	        }
268	        body << "]}";
269	    }
270	
271	    body << "]}}";
272	    return body.str();
273	}
