373	// 游标
374	// ============================================================================
375	
376	uint64_t EdgeWirelessUplinkExporter::loadWatermark() const {
377	    std::ifstream in(state_path_);
378	    if (!in) return 0;
379	    std::ostringstream oss;
380	    oss << in.rdbuf();
381	    const std::string text = oss.str();
382	
383	    const std::string ev = readUintField(text, "events_ms");
384	    if (ev.empty()) return 0;
385	    try {
386	        return static_cast<uint64_t>(std::stoull(ev));
387	    } catch (...) {
388	        // 损坏即从 0 重扫：重发由服务端幂等吸收，跳发才会真的丢事实。
389	        LOG_WARNING(weaknet_dbus::LogModule::SYSTEM,
390	                    "无线上行游标损坏，从 0 重新扫描: " << state_path_);
391	        return 0;
392	    }
393	}
394	
395	void EdgeWirelessUplinkExporter::storeWatermark(uint64_t value) {
396	    std::ofstream out(state_path_, std::ios::trunc);
397	    if (!out) {
398	        LOG_WARNING(weaknet_dbus::LogModule::SYSTEM,
399	                    "无线上行游标写入失败（下一轮将重发）: " << state_path_);
400	        return;
401	    }
402	    out << "events_ms=" << value << "\n";
403	}
