99	    const std::string body = EdgeWirelessUplinkExporter::buildBody(payload, &error);
100	    ASSERT_FALSE(body.empty()) << error;
101	
102	    // schema_version 必须逐字匹配云端 pydantic Literal
103	    EXPECT_NE(body.find("\"schema_version\":\"network.edge.wireless-events.v1\""),
104	              std::string::npos);
105	    EXPECT_NE(body.find("\"device_id\":\"radxa-cubie-a7a\""), std::string::npos);
106	    EXPECT_NE(body.find("\"watermark_ms\":1700000001500"), std::string::npos);
