    // sentinel 形式——sentinel 不在 network_pending_actions 中，服务端会
    // 丢弃，但本地日志仍保留回滚事实。
    const auto trial = config_txn_ ? config_txn_->trial() : weaknet_dbus::TrialWindow{};

