const std::vector<std::string>& trialableKeyNames() {
    // 白名单只放"采样/超时/目标 IP"这类调参键。
    // 不放 identity（edge.url/token/device_id/key_id/tenant/private_key_path）
    // 不放 enabled（开关型参数可能直接关闭监控回路）
    // 不放 bpf_obj（eBPF 程序路径变化需要重启加载，不属于运行时事务）
    // 不放 active_probe.*（探测目标变更可能让探针失联）
    static const std::vector<std::string> trialable = {
        "rtt.interval_ms", "rtt.interval", "rtt.timeout_ms", "rtt.timeout", "rtt.target",
        "rtt.window_size", "rtt.window",
        "rssi.interval_ms", "rssi.interval",
        "tcp_loss.interval_ms", "tcp_loss.interval",
        "traffic.interval_ms", "traffic.interval",
        "quality.interval_ms", "quality.interval",
        "bluetooth.interval_ms", "bluetooth.interval",
        "dns.interval_ms", "dns.interval", "dns.capture_pages",
        "tcp_connect.interval_ms", "tcp_connect.interval", "tcp_connect.capture_pages",
        "wifi_loss.interval_ms", "wifi_loss.interval",
        "http_latency.interval_ms", "http_latency.interval",
        "process_profiler.interval_ms", "process_profiler.interval",
        "tcp_retrans.interval_ms", "tcp_retrans.interval",
        "tcp_conn.interval_ms", "tcp_conn.interval",
        "skb_drop.interval_ms", "skb_drop.interval",
        "tcp_rtt.interval_ms", "tcp_rtt.interval",
        "edge.interval_ms", "edge.interval", "edge.timeout_ms", "edge.timeout",
    };
    // 指纹与二分查找都要求有序：排序只作用于副本，原始声明保持可解析形态。
    static const std::vector<std::string> sorted = [] {
        std::vector<std::string> copy = trialable;
        std::sort(copy.begin(), copy.end());
        return copy;
    }();
    return sorted;
}

namespace {

bool isTrialableKeyImpl(const std::string& key) {
    const auto& trialable = trialableKeyNames();
    return std::binary_search(trialable.begin(), trialable.end(), key);
}

/// 序列化某个 trialable key 的当前值（用于 prior_values 快照）。
/// 不复用 serializeMonitorJson —— 那个序列化整 monitor，这里要单字段。
bool snapshotMonitorParamImpl(const WeakNetConfig& cfg, const std::string& key,
                              std::string* value_out) {
    if (!value_out) return false;
====QUEUE
    def queue_action(
        self,
        context: TenantContext,
        asset_id: str,
        *,
        config_key: str,
        config_value: str,
        issued_by: str,
        approved_by: str | None = None,
        proposal_id: str | None = None,
        approval_id: str | None = None,
    ) -> str:
        """Queue a configuration change for delivery on the device's next upload.

        Each queued action gets:
          - A cryptographic anti-replay ``nonce``
          - A monotonic per-device ``generation`` (independent of config_generation)
          - Tenant scoping (enforced by TenantScopedMixin)
        """

        now = datetime.now(UTC)
        action_id = f"nact-{uuid4().hex}"
        nonce = uuid4().hex
        with self._database.transaction(context) as session:
            asset = session.get(NetworkAssetRecord, asset_id)
            if asset is None or asset.tenant_id != context.tenant_id:
                raise NetworkAssuranceNotFound(asset_id)

            # 动作 generation：每个 asset 维护自己的单调递增序列，与快照失效解耦。
            max_gen = session.execute(
                select(func.coalesce(func.max(NetworkPendingActionRecord.generation), 0)).where(
                    NetworkPendingActionRecord.tenant_id == context.tenant_id,
                    NetworkPendingActionRecord.asset_id == asset_id,
                )
            ).scalar_one()
            next_generation = int(max_gen) + 1

            session.add(
