             << ",\"p90_rtt_us\":" << summary.p90RttUs
             << ",\"p99_rtt_us\":" << summary.p99RttUs
             << ",\"min_rtt_us\":" << summary.minRttUs
             << ",\"max_rtt_us\":" << summary.maxRttUs
             << ",\"connections\":[";
        for (size_t i = 0; i < summary.topConns.size(); ++i) {
            if (i > 0) json << ",";
