     * @return 丢包率百分比；无发送段时返回 0.0 避免除零
     */
    double lossRate() const {
        if (totalSegs == 0) return 0.0;
        return (totalRetrans * 100.0) / totalSegs;
    }
};

/**
 * @brief TCP 重传监控器
