253	void start_traffic_analysis_thread(ServerContext* ctx, std::thread* worker) {
254	    *worker = std::thread([ctx](){
255	        LOG_INFO(LogModule::WEAK_MGR, "traffic analysis thread started");
256	
257	        // 动态选择接口：优先使用配置，否则取当前活动接口
258	        std::string targetIface = kDefaultTrafficInterface;
259	        if (targetIface.empty()) {
260	            // 从 WeakNetMgr 获取当前活动接口
261	            auto interfaces = ctx->weak_mgr->getCurrentInterfaces();
262	            for (const auto& iface : interfaces) {
263	                if (iface.usingNow()) {
264	                    targetIface = iface.ifName();
265	                    break;
266	                }
267	            }
268	            if (targetIface.empty()) {
269	                targetIface = "wlan0";  // 兜底默认值
270	            }
271	        }
272	
273	        LOG_INFO(LogModule::WEAK_MGR, "traffic analysis: using interface " << targetIface);
274	        // flow_rate.bpf.o 与 ProcessProfilerPlugin 共享同一份 map，使用 process_profiler
275	        // 配置块的定标参数解算容量计划；必须在 bpf_object__load 之前传入，
276	        // 否则 current_sec/process_stats 会保留内核编译期容量（真机核验发现的缺陷）
277	        ctx->weak_mgr->startTrafficAnalysis(
278	            targetIface,
279	            ctx->cfg.traffic.interval_ms.load() / 1000,
280	            weaknet::resolveScopePlan(
281	                weaknet::MapSizingScope::ProcessProfiler,
282	                {ctx->cfg.process_profiler.map_sizing.mode.get(),
283	                 ctx->cfg.process_profiler.map_sizing.entries.load(),
284	                 ctx->cfg.process_profiler.map_sizing.ram_budget_bp.load()},
285	                weaknet::totalPhysicalRamBytes()));
286	
287	        int loop_count = 0;
288	        while ((ctx->running.load() && !ctx->traffic_stop.load())) {
289	            loop_count++;
290	            LOG_INFO(LogModule::WEAK_MGR, "traffic analysis thread running, loop=" << loop_count);
291	            try {
292	                // 直接调用线程安全的流量分析更新方法
293	                LOG_INFO(LogModule::WEAK_MGR, "traffic analysis: calling updateTrafficAnalysisSafe");
294	                bool changed = ctx->weak_mgr->updateTrafficAnalysisSafe();
295	                LOG_INFO(LogModule::WEAK_MGR, "traffic analysis: updateTrafficAnalysisSafe completed, changed=" << changed);
296	
297	                // 获取当前接口列表用于日志输出
298	                auto current_interfaces = ctx->weak_mgr->getCurrentInterfaces();
299	                LOG_INFO(LogModule::WEAK_MGR, "traffic analysis: current interfaces count=" << current_interfaces.size());
300	
301	                if (changed && ctx->service) {
302	                    LOG_INFO(LogModule::WEAK_MGR, "Traffic analysis updated - emitting signal");
303	                    // 同步发射（内部有锁），不创建 detached 子线程
304	                    ctx->service->emitChanged("Traffic analysis updated", /*counter*/0);
305	                } else {
306	                    LOG_INFO(LogModule::WEAK_MGR, "TRAFFIC_ANALYSIS: no changes detected (interfaces: " << current_interfaces.size() << ")");
307	                }
308	            } catch (const std::exception& e) {
309	                LOG_ERROR(LogModule::WEAK_MGR, "Traffic analysis error: " << e.what());
310	            }
311	
312	            for (int i = 0; i < static_cast<int>(ctx->cfg.traffic.interval_ms.load() / 100) && (ctx->running.load() && !ctx->traffic_stop.load()); ++i)
313	                std::this_thread::sleep_for(100ms);
