+    // /home/radxa/weaknet，current/releases 与 data/ 同级）。
+    std::string base_dir;
+    if (const char* env = std::getenv("WEAKNET_ROOT"); env && *env) {
+        base_dir = env;
+    } else {
+        std::string data_dir = ctx_ ? ctx_->cfg.server.data_dir.get() : std::string();
