    else sqlite3_bind_null(stmt, 32);
    sqlite3_bind_int64(stmt, 33, tcp_conn_active);
    sqlite3_bind_int64(stmt, 34, tcp_conn_accepts);'''
new = '''    // 未观测一律写 NULL（与 rssi/resolved_at 同一纪律：NULL ≠ 0 —— 0 是
    // "观测到零"，会与监控线程停摆混淆）。
    const bool tcp_conn_observed = (tcp_conn_active >= 0);
    if (tcp_retrans_loss_pct >= 0) sqlite3_bind_double(stmt, 32, tcp_retrans_loss_pct);
    else sqlite3_bind_null(stmt, 32);
    if (tcp_conn_observed) sqlite3_bind_int64(stmt, 33, tcp_conn_active);
    else sqlite3_bind_null(stmt, 33);
    if (tcp_conn_observed) sqlite3_bind_int64(stmt, 34, tcp_conn_accepts);
    else sqlite3_bind_null(stmt, 34);'''
assert old in s, 'bind anchor missing'
s = s.replace(old, new)

# observed flag: only when BOTH conn samples fresh (they publish together)
old = '''        auto s_active = reg.latestGlobal(weaknet::MetricId::TCP_CONN_ACTIVE);
        if (s_active && s_active->isValid(fresh(weaknet::MetricId::TCP_CONN_ACTIVE)))
            tcp_conn_active = static_cast<int64_t>(s_active->value);
        auto s_accepts = reg.latestGlobal(weaknet::MetricId::TCP_CONN_ACCEPT_RATE);
        if (s_accepts && s_accepts->isValid(fresh(weaknet::MetricId::TCP_CONN_ACCEPT_RATE)))
            tcp_conn_accepts = static_cast<int64_t>(s_accepts->value);
    }'''
new = '''        auto s_active = reg.latestGlobal(weaknet::MetricId::TCP_CONN_ACTIVE);
        auto s_accepts = reg.latestGlobal(weaknet::MetricId::TCP_CONN_ACCEPT_RATE);
        if (s_active && s_accepts &&
            s_active->isValid(fresh(weaknet::MetricId::TCP_CONN_ACTIVE)) &&
            s_accepts->isValid(fresh(weaknet::MetricId::TCP_CONN_ACCEPT_RATE))) {
            tcp_conn_active = static_cast<int64_t>(s_active->value);
            tcp_conn_accepts = static_cast<int64_t>(s_accepts->value);
        } else {
            tcp_conn_active = -1;  // 哨兵 → 绑定 NULL
        }
    }'''
assert old in s, 'observe anchor missing'
s = s.replace(old, new)

# HistoryRow: null flag
old = '''    double tcp_retrans_loss_pct = -1;  ///< -1 = 未观测（写 NULL）
    int64_t tcp_conn_active = 0;
    int64_t tcp_conn_accepts = 0;
};'''
new = '''    double tcp_retrans_loss_pct = -1;  ///< -1 = 未观测（JSON 输出 null）
    int64_t tcp_conn_active = 0;
    int64_t tcp_conn_accepts = 0;
    bool tcp_conn_null = true;         ///< 未观测（JSON 输出 null，≠ 0）
};'''
assert old in s, 'row anchor missing'
s = s.replace(old, new)

# read: capture null
old = '''        if (sqlite3_column_type(stmt, 31) != SQLITE_NULL)
            row.tcp_retrans_loss_pct = sqlite3_column_double(stmt, 31);
        row.tcp_conn_active = sqlite3_column_int64(stmt, 32);
        row.tcp_conn_accepts = sqlite3_column_int64(stmt, 33);'''
new = '''        if (sqlite3_column_type(stmt, 31) != SQLITE_NULL)
            row.tcp_retrans_loss_pct = sqlite3_column_double(stmt, 31);
        row.tcp_conn_null = sqlite3_column_type(stmt, 32) == SQLITE_NULL;
        row.tcp_conn_active = sqlite3_column_int64(stmt, 32);
        row.tcp_conn_accepts = sqlite3_column_int64(stmt, 33);'''
assert old in s, 'read anchor missing'
s = s.replace(old, new)

# emit JSON: nulls
old = '''             << "\\"tcp_conn_active\\":" << row.tcp_conn_active << ","
             << "\\"tcp_conn_accepts\\":" << row.tcp_conn_accepts << ","'''
new = '''             << "\\"tcp_conn_active\\":" << (row.tcp_conn_null ? "null" : std::to_string(row.tcp_conn_active)) << ","
             << "\\"tcp_conn_accepts\\":" << (row.tcp_conn_null ? "null" : std::to_string(row.tcp_conn_accepts)) << ","'''
assert old in s, 'json anchor missing'
s = s.replace(old, new)
p.write_text(s)
print('null discipline applied')
PYEOF

