    std::string source;                                ///< 触发源（如网卡名 "wlan0"、服务名 "bt_monitor"）
    std::string details;                               ///< 详细信息（JSON 可选，传递更多结构化数据）
    int32_t priority = 0;                              ///< 优先级 0-10，越大越重要

