        readers.emplace_back([&]() {
            while (running.load()) {
                std::shared_lock<std::shared_mutex> lock(ctx_->monitor_pointers_mutex);
                // 关键断言：只要指针非空，其底层对象必须完整有效，绝不为野指针
                if (ctx_->wireless_event_store) {
